/*
 * Export map for libgraphics on Linux.
 *
 * libgraphics statically compiles a number of third-party C libraries
 * (libpng, libjpeg, zlib, libtiff, harfbuzz, leptonica, brotli, ...). Since
 * the library is built with -fvisibility=default, all of their symbols would
 * end up in the dynamic symbol table and interpose the system copies used by
 * GTK, gdk-pixbuf, Qt, etc. For example gdk-pixbuf would call the bundled
 * libpng 1.5 instead of the system libpng 1.6, fail to load any PNG icon and
 * make GTK abort (Euro-Office/DesktopEditors#126).
 *
 * Only export the C++ API and FreeType (used by PdfFile), hide everything else.
 */
{
  global:
    _Z*;
    FT_*;
    FTC_*;
  local:
    *;
};
